@functools.wraps(func)
def wrapper(*args, **kwargs):
    runner = None

    def handle_exception(typ, value, tb):
        # if the function throws an exception before its first "yield"
        # (or is not a generator at all), the Runner won't exist yet.
        # However, in that case we haven't reached anything asynchronous
        # yet, so we can just let the exception propagate.
        if runner is not None:
            return runner.handle_exception(typ, value, tb)
        return False
    with ExceptionStackContext(handle_exception):
        gen = func(*args, **kwargs)
        if isinstance(gen, types.GeneratorType):
            runner = Runner(gen)
            runner.run()
            return
        assert gen is None, gen

def __init__(self, gen):
    self.gen = gen
    self.yield_point = _NullYieldPoint()
    self.pending_callbacks = set()
    self.results = {}
    self.running = False
    self.finished = False
    self.exc_info = None
    self.had_exception = False

def run(self):
    """Starts or resumes the generator, running until it reaches a
    yield point that is not ready.
    """
    if self.running or self.finished:
        return
    try:
        self.running = True
        while True:
            if self.exc_info is None:
                try:
                    if not self.yield_point.is_ready():
                        return
                    next = self.yield_point.get_result()
                except Exception:
                    self.exc_info = sys.exc_info()
            try:
                if self.exc_info is not None:
                    self.had_exception = True
                    exc_info = self.exc_info
                    self.exc_info = None
                    yielded = self.gen.throw(*exc_info)
                else:
                    yielded = self.gen.send(next)
            except StopIteration:
                self.finished = True
                if self.pending_callbacks and not self.had_exception:
                    # If we ran cleanly without waiting on all callbacks
                    # raise an error (really more of a warning).  If we
                    # had an exception then some callbacks may have been
                    # orphaned, so skip the check in that case.
                    raise LeakedCallbackError(
                        "finished without waiting for callbacks %r" %
                        self.pending_callbacks)
                return
            except Exception:
                self.finished = True
                raise
            if isinstance(yielded, list):
                yielded = Multi(yielded)
            if isinstance(yielded, YieldPoint):
                self.yield_point = yielded
                try:
                    self.yield_point.start(self)
                except Exception:
                    self.exc_info = sys.exc_info()
            else:
                self.exc_info = (BadYieldError("yielded unknown object %r" % yielded),)
    finally:
        self.running = False

