                            "@gen.engine functions cannot return values: "
                            "%r" % result)
                    assert value is None
                    deactivate()
                runner = Runner(result, final_callback)
                runner.run()
                return
        if result is not None:
            raise ReturnValueIgnoredError(
                "@gen.engine functions cannot return values: %r" % result)
        deactivate()

