        base, query = url.split('?', 1)
        parameters = [pair.split(kvsep, 1) for pair in query.split(sep)]
    except:
        base = url
        query = ""
        parameters = []

    # unique parameters while keeping order
    unique = {}
    querylist = []
    for pair in parameters: 
        k = pair[0]
        if not unique.get(k):
