        tqdm_auto.write(str(e))
    else:
        self.message_id = res.json()['result']['message_id']

def write(self, s):
    """Replaces internal `message_id`'s text with `s`."""
    if not s:
        return
    s = s.strip().replace('\r', '')
    if s == self.text:
        return  # avoid duplicate message Bot error
    self.text = s
    try:
        f = self.pool.submit(
            self.session.post,
            self.API + '%s/editMessageText' % self.token,
            data=dict(
                text='`' + s + '`', chat_id=self.chat_id,
                message_id=self.message_id, parse_mode='MarkdownV2'))
    except Exception as e:
        tqdm_auto.write(str(e))
    else:
        self.futures.append(f)
        return f

def flush(self):
    """Ensure the last `write` has been processed."""
    [f.cancel() for f in self.futures[-2::-1]]
    try:
        return self.futures[-1].result()
    except IndexError:
        pass
    finally:
        self.futures = []

def get_authenticated_user(self, redirect_uri, client_id, client_secret,
                          code, callback, extra_fields=None):
  """ Handles the login for the Facebook user, returning a user object.

  Example usage:
  class FacebookGraphLoginHandler(LoginHandler, tornado.auth.FacebookGraphMixin):
    @tornado.web.asynchronous
    def get(self):
        if self.get_argument("code", False):
            self.get_authenticated_user(
              redirect_uri='/auth/facebookgraph/',
              client_id=self.settings["facebook_api_key"],
              client_secret=self.settings["facebook_secret"],
              code=self.get_argument("code"),
              callback=self.async_callback(
                self._on_login))
            return
        self.authorize_redirect(redirect_uri='/auth/facebookgraph/',
                                client_id=self.settings["facebook_api_key"],
                                extra_params={"scope": "read_stream,offline_access"})

    def _on_login(self, user):
      logging.error(user)
      self.finish()

  """
  http = httpclient.AsyncHTTPClient()
  args = {
    "redirect_uri": redirect_uri,
    "code": code,
    "client_id": client_id,
    "client_secret": client_secret,
  }

  if extra_fields and not isinstance(extra_fields, (set, frozenset)):
      extra_fields = set(extra_fields)

  http.fetch(self._oauth_request_token_url(**args),
      self.async_callback(self._on_access_token, redirect_uri, client_id,
                          client_secret, callback, extra_fields))

def _on_access_token(self, redirect_uri, client_id, client_secret,
                    callback, extra_fields, response):
  if response.error:
      logging.warning('Facebook auth error: %s' % str(response))
      callback(None)
      return

  session = {
      "access_token": cgi.parse_qs(response.body)["access_token"][-1],
      "expires": cgi.parse_qs(response.body).get("expires")
  }

  self.facebook_request(
      path="/me",
      callback=self.async_callback(
          self._on_get_user_info, callback, session, extra_fields),
      access_token=session["access_token"],
      fields="picture" # This one's exceptional in that it appends to fields returned
      )

def _on_get_user_info(self, callback, session, extra_fields, user):
    if user is None:
        callback(None)
        return

    fields = set(['id', 'name', 'first_name', 'last_name', 'locale', 'picture', 'link'])
    if extra_fields: fields.update(extra_fields)

    fieldmap = {}
    for field in fields:
        fieldmap[field] = user.get(field)

    fieldmap.update({"access_token": session["access_token"], "session_expires": session.get("expires")})
    callback(fieldmap)
